def extract(tree):
    rows = tree.where(content_desc="group.balance")
    if not rows:
        raise ValueError("The group balance text is absent")
    return rows[0]["text"]

def extract(tree):
    rows = tree.where(content_desc="extension.active")
    if not rows:
        raise ValueError("The extension status banner is absent")
    text = rows[0]["text"]
    return bool(re.fullmatch(r"Extension active, ends at (?:[01]\d|2[0-3]):[0-5]\d", text))
